+            val set = sets.optJSONObject(i) ?: continue
+            val setGameId = set.optInt("GameId").takeIf { it > 0 } ?: topLevelGameId
+            val achievements = set.optJSONArray("Achievements") ?: continue
+            for (j in 0 until achievements.length()) {
